  static string Project {get{return Path.GetDirectoryName(Application.dataPath);}}
  static string Full(string s){return Path.GetFullPath(s).TrimEnd('\\','/').Replace('\\','/');}
  public static Dictionary<string,string> Pins(string file){var d=new Dictionary<string,string>(StringComparer.Ordinal);foreach(string line in File.ReadAllLines(file)){var s=line.Split('\t');if(s.Length!=2||!System.Text.RegularExpressions.Regex.IsMatch(s[1],"^[0-9a-f]{64}$")||s[0].Split('/').Any(x=>x==""||x=="."||x=="..")||s[0].Contains("\\")||s[0].Contains(":")||s[0].StartsWith("/")||!new[]{"Assets","Packages","ProjectSettings"}.Contains(s[0].Split('/')[0])||d.ContainsKey(s[0]))throw new InvalidOperationException("Invalid full pin TSV");d.Add(s[0],s[1]);}if(d.Count==0)throw new InvalidOperationException("Empty pins");return d;}
  public static void RequireBatch(bool batch){if(!batch)throw new InvalidOperationException("Batch operational entrypoint only");}
  static Attestation Admit(string action){
   RequireBatch(Application.isBatchMode);PerformanceBuildPolicy.Boundaries(Project); // recursive reparse checks FIRST
   string expected="{\"owner\": \"performance-exact-source-v1\", \"root\": \""+Full(PerformanceBuildPolicy.Root)+"\"}";
   if(File.ReadAllText(Path.Combine(Project,".performance-owned-stage.json"))!=expected)throw new InvalidOperationException("Exact Python stage marker required");
   string token=null;foreach(string a in Environment.GetCommandLineArgs())if(a.StartsWith("--performance-native-token=",StringComparison.Ordinal)){if(token!=null)throw new InvalidOperationException("Duplicate native token");token=a.Substring("--performance-native-token=".Length);}
   string file=Path.Combine(Project,".performance-native-attestation.json");
   if(token==null||token!=Phase5BuildPolicy.Hash(file))throw new InvalidOperationException("Trusted parent CLI attestation token required; menus alone are never authority");
   var v=JsonUtility.FromJson<Attestation>(File.ReadAllText(file));
   if(v==null||v.root!=Full(PerformanceBuildPolicy.Root)||v.stage!=Full(Project)||v.candidate!=Full(Path.Combine(v.root,PerformanceBuildPolicy.CandidateRelative))||v.action!=action)throw new InvalidOperationException("Attested exact action/boundaries");
   string[] names={".performance-root-pins.tsv",".performance-stage-pins.tsv",".performance-meta-allowlist.json",".performance-builder-input.json"};string[] hashes={v.rootPinsSHA,v.stagePinsSHA,v.metaAllowlistSHA,v.builderInputSHA};for(int i=0;i<names.Length;i++)if(Phase5BuildPolicy.Hash(Path.Combine(Project,names[i]))!=hashes[i])throw new InvalidOperationException("Attested data drift");
   var source=Pins(Path.Combine(Project,names[0]));var staged=Pins(Path.Combine(Project,names[1]));
   var allowance=JsonUtility.FromJson<MetaAllowance>(File.ReadAllText(Path.Combine(Project,names[2])));if(allowance==null||allowance.assets==null||allowance.folders==null)throw new InvalidOperationException("Explicit file/folder metadata allowlist required");
   PerformanceBuildPolicy.AdmitClosure(v.root,Project,source,staged,allowance.assets,allowance.folders,action);return v;
  }
  const string ProfilePath="Assets/VintageCollector/Media/Phase5/NativeBasePerformanceProfile.asset";
  const string OldScene="Assets/VintageCollector/Scenes/BootstrapSuppliedExpansionArt.unity";
  static Input Read(){var v=JsonUtility.FromJson<Input>(File.ReadAllText(Path.Combine(Project,".performance-builder-input.json")));if(v==null||v.schemaVersion!=1||v.generation!=Generation||v.files==null||v.files.Length!=109||v.profile==null||v.profile.generationId!=Generation||v.profile.printingId!="base-en-unlimited1999"||v.profile.cards.Length!=101||v.profile.wrapperFronts.Length!=3)throw new InvalidOperationException("Frozen Base input shape");var seen=new HashSet<string>(StringComparer.Ordinal);foreach(var f in v.files){if(!seen.Add(f.targetPath)||!f.targetPath.StartsWith("Assets/Supplied/PerformanceBase/generations/"+Generation+"/",StringComparison.Ordinal)||f.targetPath.Contains("..")||f.targetPath.Contains("\\")||f.targetPath.Contains(":")||f.sourceSha256!=f.copySha256||Phase5BuildPolicy.Hash(Path.Combine(Project,f.targetPath))!=f.copySha256||Phase5BuildPolicy.Hash(Path.Combine(Project,f.sourcePath))!=f.sourceSha256||f.maxTextureSize!=1024||f.mipmaps||!f.readable||f.linear==f.sRGB||f.compression!="Uncompressed"||f.filterMode!="Bilinear"||f.wrapMode!="Clamp")throw new InvalidOperationException("Exact Base byte/import authority");}return v;}
  static void Absent(string path){if(File.Exists(Path.Combine(Project,path))||File.Exists(Path.Combine(Project,path+".meta")))throw new InvalidOperationException("New-only authoring; no overwrite");}
  static Texture2D Tex(string path){if(string.IsNullOrEmpty(path))return null;var value=AssetDatabase.LoadAssetAtPath<Texture2D>(path);if(value==null)throw new InvalidOperationException("Missing native texture "+path);return value;}
  static string HashBytes(byte[] bytes){using(var h=System.Security.Cryptography.SHA256.Create())return BitConverter.ToString(h.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();}
  static void VerifyPixels(Input input){foreach(var f in input.files){var t=Tex(f.targetPath);var importer=AssetImporter.GetAtPath(f.targetPath) as TextureImporter;if(importer==null||t.width!=f.width||t.height!=f.height||importer.sRGBTexture!=f.sRGB||importer.mipmapEnabled||!importer.isReadable||importer.maxTextureSize!=1024||importer.textureCompression!=TextureImporterCompression.Uncompressed||importer.wrapMode!=TextureWrapMode.Clamp||importer.filterMode!=FilterMode.Bilinear||importer.npotScale!=TextureImporterNPOTScale.None)throw new InvalidOperationException("Native dimensions/import settings");var pixels=t.GetPixels32();var bytes=new byte[checked(f.width*f.height*4)];for(int y=0;y<f.height;y++)for(int x=0;x<f.width;x++){var p=pixels[(f.height-1-y)*f.width+x];int i=(y*f.width+x)*4;bytes[i]=p.r;bytes[i+1]=p.g;bytes[i+2]=p.b;bytes[i+3]=p.a;}if(HashBytes(bytes)!=f.rgbaSha256)throw new InvalidOperationException("Full native RGBA identity with normalized row order");}}
  public static void CreateAssets(){Admit("CreateAssets");var input=Read();Absent(ProfilePath);
   foreach(var f in input.files){var importer=AssetImporter.GetAtPath(f.targetPath) as TextureImporter;if(importer==null)throw new InvalidOperationException("Imported new PNG required");importer.textureType=TextureImporterType.Default;importer.npotScale=TextureImporterNPOTScale.None;importer.mipmapEnabled=false;importer.isReadable=true;importer.maxTextureSize=1024;importer.textureCompression=TextureImporterCompression.Uncompressed;importer.sRGBTexture=f.sRGB;importer.wrapMode=TextureWrapMode.Clamp;importer.filterMode=FilterMode.Bilinear;importer.SaveAndReimport();}
   VerifyPixels(input);var p=input.profile;var asset=ScriptableObject.CreateInstance<NativeBaseMediaProfile>();asset.printingId=p.printingId;asset.generationId=p.generationId;asset.displayLabel=p.displayLabel;asset.cards=p.cards.Select(c=>new NativeBaseCardRow{canonicalId=c.canonicalId,face=Tex(c.face),mask=Tex(c.mask)}).ToArray();asset.sharedCardBack=Tex(p.sharedCardBack);asset.wrapperFronts=p.wrapperFronts.Select(Tex).ToArray();asset.wrapperBack=Tex(p.wrapperBack);asset.wrapperFrontMask=Tex(p.wrapperFrontMask);asset.wrapperBackMask=Tex(p.wrapperBackMask);AssetDatabase.CreateAsset(asset,ProfilePath);AssetDatabase.SaveAssets();ValidateAssets(input);
  }
  static void ValidateAssets(Input input){VerifyPixels(input);var p=AssetDatabase.LoadAssetAtPath<NativeBaseMediaProfile>(ProfilePath);var q=input.profile;if(p==null||p.printingId!=q.printingId||p.generationId!=q.generationId||p.displayLabel!=q.displayLabel||p.cards.Length!=101||p.wrapperFronts.Length!=3)throw new InvalidOperationException("Native Base SO identity");for(int i=0;i<101;i++)if(p.cards[i].canonicalId!=q.cards[i].canonicalId||p.cards[i].face!=Tex(q.cards[i].face)||p.cards[i].mask!=Tex(q.cards[i].mask))throw new InvalidOperationException("Native Base card binding");if(p.sharedCardBack!=Tex(q.sharedCardBack)||p.wrapperBack!=Tex(q.wrapperBack)||p.wrapperFrontMask!=Tex(q.wrapperFrontMask)||p.wrapperBackMask!=Tex(q.wrapperBackMask)||!p.wrapperFronts.SequenceEqual(q.wrapperFronts.Select(Tex)))throw new InvalidOperationException("Exact wrapper/back fields");}
  static OpeningGame Open(string path){var scene=EditorSceneManager.OpenScene(path,OpenSceneMode.Single);var games=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<OpeningGame>(true)).ToArray();if(games.Length!=1)throw new InvalidOperationException("Exactly one retained controller");return games[0];}
  static Type Probe(string name){var types=AppDomain.CurrentDomain.GetAssemblies().Select(a=>a.GetType("VintageCollector.Verification."+name,false)).Where(t=>t!=null).ToArray();if(types.Length!=1||!typeof(MonoBehaviour).IsAssignableFrom(types[0]))throw new InvalidOperationException("Native precondition: reviewed runtime probe missing: "+name);return types[0];}
  public static void CreateBootstrap(){Admit("CreateBootstrap");foreach(string path in PerformanceBuildPolicy.Scenes)Absent(path);var input=Read();ValidateAssets(input);var smoke=Probe("PerformanceSmokeProbe");var timing=Probe("PerformanceBootTimingProbe");if(!AssetDatabase.CopyAsset(OldScene,Scene))throw new IOException("Clone retained supplied-art scene failed");var game=Open(Scene);var host=game.GetComponent<Phase5MediaHost>();if(host==null)throw new InvalidOperationException("Retained media owner missing");host.nativeBaseMediaProfile=AssetDatabase.LoadAssetAtPath<NativeBaseMediaProfile>(ProfilePath);game.backgroundOpeningStorage=true;game.phase5Sets.Single(c=>c.printingId==input.profile.printingId).wrapperFronts=input.profile.wrapperFronts.Select(Tex).ToArray();foreach(var component in game.gameObject.scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MonoBehaviour>(true)))if(component!=null&&(component.GetType().FullName=="VintageCollector.Verification.SuppliedArtSmokeProbe"||component.GetType().FullName=="VintageCollector.Verification.Phase5SmokeProbe"))UnityEngine.Object.DestroyImmediate(component);game.gameObject.AddComponent(smoke);EditorSceneManager.MarkSceneDirty(game.gameObject.scene);if(!EditorSceneManager.SaveScene(game.gameObject.scene,Scene))throw new IOException("Save heavy clone");
   var light=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var root=new GameObject("Performance startup coordinator");root.AddComponent<StartupLoadingCoordinator>().heavySceneName="BootstrapPerformance";new GameObject("Performance startup timing").AddComponent(timing);var camera=new GameObject("Startup camera").AddComponent<Camera>();camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=Color.black;if(!EditorSceneManager.SaveScene(light,PerformanceBuildPolicy.Startup))throw new IOException("Save lightweight scene");AssetDatabase.SaveAssets();ValidateScene(input);PrepareRecipeCore();DiskRecipe();}
  static void ValidateScene(Input input){ValidateAssets(input);var game=Open(Scene);var host=game.GetComponent<Phase5MediaHost>();if(host==null||host.nativeBaseMediaProfile!=AssetDatabase.LoadAssetAtPath<NativeBaseMediaProfile>(ProfilePath)||!game.backgroundOpeningStorage||host.suppliedCardArtProfiles==null||host.suppliedCardArtProfiles.Length!=2||!game.phase5Sets.Single(c=>c.printingId==input.profile.printingId).wrapperFronts.SequenceEqual(input.profile.wrapperFronts.Select(Tex))||game.GetComponent(Probe("PerformanceSmokeProbe"))==null)throw new InvalidOperationException("Reopened heavy profile/async/probe bindings");foreach(var component in game.gameObject.scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MonoBehaviour>(true)))if(component!=null&&(component.GetType().Name=="SuppliedArtSmokeProbe"||component.GetType().Name=="Phase5SmokeProbe"))throw new InvalidOperationException("Old probes forbidden only on new clone");var light=EditorSceneManager.OpenScene(PerformanceBuildPolicy.Startup,OpenSceneMode.Single);var owners=light.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<StartupLoadingCoordinator>(true)).ToArray();if(owners.Length!=1||owners[0].heavySceneName!="BootstrapPerformance"||owners[0].GetComponent(Probe("PerformanceBootTimingProbe"))!=null||light.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MonoBehaviour>(true)).Count(c=>c!=null&&c.GetType()==Probe("PerformanceBootTimingProbe"))!=1||light.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<OpeningGame>(true)).Any()||light.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Phase5MediaHost>(true)).Any())throw new InvalidOperationException("Asset-free startup scene");if(AssetDatabase.GetDependencies(PerformanceBuildPolicy.Startup,true).Any(n=>n.StartsWith("Assets/Supplied/",StringComparison.Ordinal)||n.StartsWith("Assets/VintageCollector/Media/Phase5/",StringComparison.Ordinal)||n.EndsWith(".png",StringComparison.OrdinalIgnoreCase)||n.EndsWith(".wav",StringComparison.OrdinalIgnoreCase)))throw new InvalidOperationException("Heavy dependency in lightweight startup scene");foreach(string path in PerformanceBuildPolicy.Scenes)if(AssetDatabase.AssetPathToGUID(path).Length!=32)throw new InvalidOperationException("Native scene GUID");}
  static void PrepareRecipeCore(){if(PlayerSettings.defaultScreenWidth!=1280||PlayerSettings.defaultScreenHeight!=720||PlayerSettings.fullScreenMode!=FullScreenMode.Windowed||EditorUserBuildSettings.development||PlayerSettings.GetScriptingBackend(NamedBuildTarget.Standalone)!=ScriptingImplementation.Mono2x||PlayerSettings.GetUseDefaultGraphicsAPIs(BuildTarget.StandaloneWindows64)||!PlayerSettings.GetGraphicsAPIs(BuildTarget.StandaloneWindows64).SequenceEqual(new[]{GraphicsDeviceType.Direct3D11}))throw new InvalidOperationException("Root release defaults required; never rewrite settings");byte[] recipe=PerformanceBuildPolicy.RecipeBytes(PerformanceBuildPolicy.Root,Project);EditorBuildSettings.scenes=PerformanceBuildPolicy.Scenes.Select(s=>new EditorBuildSettingsScene(s,true)).ToArray();File.WriteAllBytes(Path.Combine(Project,PerformanceBuildPolicy.Settings),recipe);}

  static void DiskRecipe(){if(!File.ReadAllBytes(Path.Combine(Project,PerformanceBuildPolicy.Settings)).SequenceEqual(PerformanceBuildPolicy.RecipeBytes(PerformanceBuildPolicy.Root,Project)))throw new InvalidOperationException("Exact TWO-scene disk recipe required");}
  public static void PrepareReleaseRecipe(){Admit("CreateBootstrap");PrepareRecipeCore();DiskRecipe();}
  public static void BuildWindows(){var a=Admit("BuildWindows");var input=Read();ValidateScene(input);if(PlayerSettings.defaultScreenWidth!=1280||PlayerSettings.defaultScreenHeight!=720||PlayerSettings.fullScreenMode!=FullScreenMode.Windowed||EditorBuildSettings.scenes.Length!=2||!EditorBuildSettings.scenes.Select(s=>s.path).SequenceEqual(PerformanceBuildPolicy.Scenes)||EditorBuildSettings.scenes.Any(s=>!s.enabled)||EditorUserBuildSettings.development||PlayerSettings.GetScriptingBackend(NamedBuildTarget.Standalone)!=ScriptingImplementation.Mono2x||PlayerSettings.GetUseDefaultGraphicsAPIs(BuildTarget.StandaloneWindows64)||!PlayerSettings.GetGraphicsAPIs(BuildTarget.StandaloneWindows64).SequenceEqual(new[]{GraphicsDeviceType.Direct3D11}))throw new InvalidOperationException("Frozen release recipe required before pins");DiskRecipe();var before=Phase5BuildPolicy.AllInputs(Project);Directory.CreateDirectory(a.candidate);File.WriteAllText(Path.Combine(a.candidate,".performance-candidate-owner.txt"),"performance-exact-source-v1\n"+a.root+"\n");var report=BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=PerformanceBuildPolicy.Scenes,target=BuildTarget.StandaloneWindows64,locationPathName=Path.Combine(a.candidate,"VintageCardCollector.exe"),options=BuildOptions.None});PerformanceBuildPolicy.ExactClosure(Project,before);if(report.summary.result!=BuildResult.Succeeded||report.summary.totalErrors!=0||report.summary.totalWarnings!=0)throw new InvalidOperationException("Native build must have zero warnings/errors");var candidate=new List<Pin>();Phase5BuildPolicy.RequireRegularTree(a.candidate);foreach(string p in Directory.GetFiles(a.candidate,"*",SearchOption.AllDirectories))candidate.Add(new Pin{path=Full(p).Substring(a.candidate.Length+1),sha256=Phase5BuildPolicy.Hash(p)});File.WriteAllText(Path.Combine(Project,".performance-build-report.json"),JsonUtility.ToJson(new Evidence{passed=true,compilerPins=before.Select(p=>new Pin{path=p.Key,sha256=p.Value}).ToArray(),candidat